3010	template <typename TIn, typename TOut>
3011	static void launch(const at::Tensor& q, const at::Tensor& k, const at::Tensor& v,
3012	                   at::Tensor& out, at::Tensor& lse,
3013	                   const at::Tensor& cu_q, const std::optional<at::Tensor>& cu_k,
3014	                   const std::optional<at::Tensor>& seqused_k, const std::optional<at::Tensor>& page_table,
3015	                   const std::optional<at::Tensor>& qd, const std::optional<at::Tensor>& kd, const std::optional<at::Tensor>& vd,
3016	                   int b, int hq, int hkv, int hd, int hdv, int total_q,
3017	                   double scale, double softcap, int win_l, int win_r, bool causal, cudaStream_t stream) {
3018	  Params<TIn, TOut> p{};
3019	  p.q = (const TIn*)dptr(q); p.k = (const TIn*)dptr(k); p.v = (const TIn*)dptr(v);
3020	  p.o = (TOut*)out.data_ptr(); p.lse = (float*)lse.data_ptr();
3021	  p.cu_q = (const int*)cu_q.data_ptr();
3022	  p.cu_k = cu_k ? (const int*)cu_k->data_ptr() : nullptr;
3023	  p.seqused_k = seqused_k ? (const int*)seqused_k->data_ptr() : nullptr;
3024	  p.page_table = page_table ? (const int*)page_table->data_ptr() : nullptr;
3025	  p.page_stride = page_table ? (int)page_table->stride(0) : 0;
3026	  p.block_size = (page_table) ? (int)k.size(1) : 0;
3027	  p.q_descale = qd ? (const float*)qd->data_ptr() : nullptr;
3028	  p.k_descale = kd ? (const float*)kd->data_ptr() : nullptr;
3029	  p.v_descale = vd ? (const float*)vd->data_ptr() : nullptr;
3030	  // Descale strides IN ELEMENTS (broadcast-safe: a (b,hkv) tensor with stride [0,0] -> 0,0).
3031	  p.ds_b = qd ? (int)qd->stride(0) : 0;
3032	  p.ds_h = qd ? (int)qd->stride(1) : 0;
3033	  p.q_row = q.stride(0); p.q_head = q.stride(1);
3034	  // k/v paged (nblocks, block, hkv, hd): index krow over flattened (blk*block_size+off),
3035	  // so row stride = stride(1), head stride = stride(2). Non-paged: row stride(0), head stride(1).
3036	  if (page_table) { p.k_row = k.stride(1); p.k_head = k.stride(2); p.v_row = v.stride(1); p.v_head = v.stride(2); }
3037	  else            { p.k_row = k.stride(0); p.k_head = k.stride(1); p.v_row = v.stride(0); p.v_head = v.stride(1); }
3038	  p.o_row = out.stride(0); p.o_head = out.stride(1);
3039	  p.b = b; p.hq = hq; p.hkv = hkv; p.hd = hd; p.hdv = hdv; p.total_q = total_q;
3040	  p.scale = (float)scale; p.softcap = (float)softcap; p.win_l = win_l; p.win_r = win_r; p.causal = causal;
3041	  long pairs = (long)total_q * hq;
3042	  int threads = 128; long warps_per_block = threads / 32;
3043	  long blocks = (pairs + warps_per_block - 1) / warps_per_block;
3044	  attn_kernel<TIn, TOut><<<(unsigned)blocks, threads, 0, stream>>>(p);
3045	}
