3047	static int mha_num_sm() {
3048	  static int num_sm = 0;
3049	  if (num_sm == 0) { int dev = 0; cudaGetDevice(&dev); cudaDeviceGetAttribute(&num_sm, cudaDevAttrMultiProcessorCount, dev); if (num_sm <= 0) num_sm = 132; }
3050	  return num_sm;
3051	}
