3055	    std::optional<at::Tensor> k_new, std::optional<at::Tensor> v_new, std::optional<at::Tensor> q_v,
3056	    std::optional<at::Tensor> out_,
3057	    std::optional<at::Tensor> cu_seqlens_q, std::optional<at::Tensor> cu_seqlens_k, std::optional<at::Tensor> cu_seqlens_k_new,
3058	    std::optional<at::Tensor> seqused_q, std::optional<at::Tensor> seqused_k,
3059	    std::optional<int64_t> max_seqlen_q, std::optional<int64_t> max_seqlen_k,
3060	    std::optional<at::Tensor> page_table, std::optional<at::Tensor> kv_batch_idx, std::optional<at::Tensor> leftpad_k,
3061	    std::optional<at::Tensor> rotary_cos, std::optional<at::Tensor> rotary_sin, std::optional<at::Tensor> seqlens_rotary,
3062	    std::optional<at::Tensor> q_descale, std::optional<at::Tensor> k_descale, std::optional<at::Tensor> v_descale,
3063	    double softmax_scale, bool is_causal, int64_t window_size_left, int64_t window_size_right,
3064	    double softcap, bool is_rotary_interleaved,
3065	    std::optional<at::Tensor> scheduler_metadata, int64_t num_splits, std::optional<bool> pack_gqa, int64_t sm_margin,
3066	    std::optional<at::Tensor> s_aux, int64_t cp_world_size, int64_t cp_rank, std::optional<at::Tensor> cp_tot_seqused_k) {
3067	  const at::cuda::OptionalCUDAGuard guard(q.device());
3068	  auto stream = at::cuda::getCurrentCUDAStream();
3069	
3070	  int total_q = (int)q.size(0);
3071	  int hq = (int)q.size(1);
3072	  int hd = (int)q.size(2);
3073	  bool paged = page_table.has_value();
3074	  int hkv = paged ? (int)k.size(2) : (int)k.size(1);
3075	  int hdv = paged ? (int)v.size(3) : (int)v.size(2);
3076	  int b = (int)cu_seqlens_q->size(0) - 1;
3077	
3078	  bool is_fp8 = q.scalar_type() == at::kFloat8_e4m3fn;
3079	  auto out_dtype = is_fp8 ? at::kBFloat16 : q.scalar_type();
3080	  at::Tensor out = out_.has_value() ? *out_
3081	                 : at::empty({total_q, hq, hdv}, q.options().dtype(out_dtype));
3082	  at::Tensor lse = at::empty({hq, total_q}, q.options().dtype(at::kFloat));
3083	
3084	  int win_l = (int)window_size_left, win_r = (int)window_size_right;
3085	
3086	  // Attention sink (s_aux): per-(query)head logit added to the softmax denominator. Converted to a
3087	  // float scratch (kept alive until mha_fwd returns; freed only after the same-stream kernel runs, so
3088	  // the async launch is safe). cache_leftpad (leftpad_k): per-batch count of leading KV tokens to skip.
3089	  at::Tensor s_aux_f;
3090	  const float* s_aux_ptr = nullptr;
3091	  if (s_aux.has_value()) { s_aux_f = s_aux->to(at::kFloat).contiguous(); s_aux_ptr = (const float*)s_aux_f.data_ptr(); }
3092	  const int* leftpad_ptr = leftpad_k.has_value() ? (const int*)leftpad_k->data_ptr() : nullptr;
3093	  bool causal = is_causal;
3094	
3095	  // FAST PATH routing: two wgmma paths cover EVERY supported shape -- the split-KV decode kernel for
3096	  // small/medium packed-M decode/append/spec (q <= 32 AND q*rep <= 64, i.e. one DCM=64 M-tile) and the
3097	  // prefill kernel for everything else (larger q, incl. q >= 64 prompts and rep > 16 past 64 rows).
3098	  // BOTH implement softcap + sliding-window via the EXTRA template, so neither is gated at dispatch.
3099	  // `can_prefill` is defined AFTER the decode predicate below so it can defer to it (the prefill kernel
3100	  // is correct for small q too, but split-KV decode parallelizes long context that prefill cannot).
3101	  bool hd_ok = ((hd == hdv) && (hd == 64 || hd == 96 || hd == 128 || hd == 192 || hd == 256)) ||
3102	               (hd == 192 && hdv == 128);  // FA3 flash_fwd_hdimdiff: d=192 -> dv=128 (prefill + decode)
3103	  bool dt16_ok = (q.scalar_type() == at::kBFloat16) || (q.scalar_type() == at::kHalf);  // bf16/fp16 share layout
3104	  bool dtwg_ok = dt16_ok || is_fp8;  // wgmma fast path: bf16/fp16 native, fp8 via convert->bf16 smem + descale
3105	
3106	  // DECODE fast path: small q_len (decode/append/spec/medium-q). Flash-decoding + split-KV + combine.
3107	  // Generic over dtype (bf16/fp16/fp8 descale-folded), GQA/MQA, softcap, sliding-window, paged.
3108	  // The split-KV kernel runs the prefill mainloop with DCM=64 (one consumer warpgroup), so it packs
3109	  // up to 64 q*rep rows into ONE M-tile -- the lever it adds over prefill is splitting a long KV
3110	  // context across CTAs (+ combine), which is exactly what a small-q / long-context request needs and
3111	  // the single-CTA prefill path cannot do. Cap at max_q<=32 (keep large-q prompts q>=64 on the CM=128
3112	  // prefill path) and q*rep<=64 (one DCM tile, right-sized -- CM=128 would waste a warpgroup on masked
3113	  // rows). Requires contiguous head-dim.
3114	  bool dt_ok = (q.scalar_type() == at::kBFloat16) || (q.scalar_type() == at::kHalf) || is_fp8;
3115	  bool dhd_ok = (hd % 32 == 0) && (hdv % 32 == 0) &&
3116	                ((hd == 64 && hdv == 64) || (hd == 96 && hdv == 96) || (hd == 128 && hdv == 128) ||
3117	                 (hd == 192 && hdv == 192) || (hd == 256 && hdv == 256) || (hd == 192 && hdv == 128));
3118	  bool contig_hd = q.stride(2) == 1 &&
3119	                   (paged ? (k.stride(3) == 1 && v.stride(3) == 1) : (k.stride(2) == 1 && v.stride(2) == 1));
3120	  int rep = (hq % hkv == 0) ? hq / hkv : 0;
3121	  int max_q = max_seqlen_q.has_value() ? (int)max_seqlen_q.value() : total_q;
3122	  bool can_decode = dt_ok && dhd_ok && contig_hd && (hq % hkv == 0) &&
3123	                    max_q >= 1 && max_q <= 32 && (max_q * rep) <= 64;
3124	  int max_klen = max_seqlen_k.has_value() ? (int)max_seqlen_k.value() : 0;
3125	  // FAST decode: the wgmma prefill mainloop + split-KV (reuses TMA/async-pipelined loads, softcap+SWA).
3126	  // Limited to what that kernel supports (bf16/fp16/fp8-convert, hd==hdv in {64,128}); rest use warp path.
3127	  bool can_decode_fast = can_decode && dtwg_ok &&
3128	                         (((hd == hdv) && (hd == 64 || hd == 96 || hd == 128 || hd == 192 || hd == 256)) ||
3129	                          (hd == 192 && hdv == 128));
3130	  // Prefill wgmma path: ANY q >= 1 that the small-q decode path does not claim. Covers q >= 64 prompts,
3131	  // the medium-q 5..63 band, and rep > 16 at small q -- the prefill kernel packs q*rep into its M tiles
3132	  // (token = row/rep, qhead = hk*rep + row%rep) with no <=16-row cap, so arbitrary q/rep are correct.
3133	  // softcap + sliding-window are handled by launch_prefill's EXTRA dispatch. Deferring via
3134	  // !can_decode_fast keeps every existing decode config on the (faster) decode kernel -> no regression.
3135	  bool can_prefill = dtwg_ok && hd_ok && (hq % hkv == 0) &&
3136	                     max_seqlen_q.has_value() && max_seqlen_q.value() >= 1 && !can_decode_fast;
3137	
3138	  // UNDERFILLED prefill -> split-KV decode. The CM=128 prefill grid is tiles_m*hkv*b CTAs (one wave,
3139	  // num_splits=1); when batch*heads*m-tiles is small over a LONG context that leaves most SMs idle and
3140	  // exposes the full DRAM latency (e.g. q120/k4224: 2*8*4 = 64 CTAs on 132 SMs -> 0.48 wave, ~0.81x).
3141	  // The split-KV decode path runs the SAME prefill mainloop at CM=64 (2x m-tiles), picks a wave-filling
3142	  // split count, and uses the deep STAGES=5 K/V pipeline -- exactly the long-context latency-hiding the
3143	  // single-wave prefill lacks. Gated to the decode-path head dims + long ctx + modest q so well-filled
3144	  // prefills (dense batch>=2, q>=256, or short ctx) are untouched (they measure better on CM=128).
3145	  int pf_tiles_m = (max_q * rep + 128 - 1) / 128;
3146	  long pf_base = (long)pf_tiles_m * (long)hkv * (long)b;
3147	  bool decode_caps = ((hd == hdv) && (hd == 64 || hd == 96 || hd == 128 || hd == 192 || hd == 256)) ||
3148	                     (hd == 192 && hdv == 128);
3149	  bool pf_underfill = can_prefill && dhd_ok && contig_hd && decode_caps && rep >= 1 &&
3150	                      (pf_base * 2 <= (long)mha_num_sm()) && max_klen >= 2048 && max_q > 32 && max_q <= 256;
3151	
3152	  if (total_q > 0 && can_prefill && !pf_underfill) {
3153	    // descale: nullopt for bf16/fp16 (vLLM passes a stride-0 broadcast that must be IGNORED); real
3154	    // q/k/v_descale for fp8 (folded: qd*kd into the softmax scale, vd into O at the epilogue).
3155	#define PF_RT(TIN_, TC_, QD_, KD_, VD_)                                                                 \
3156	    pf::launch_prefill<TIN_, TC_>(q, k, v, out, lse, *cu_seqlens_q, cu_seqlens_k, seqused_k, page_table, \
3157	        QD_, KD_, VD_, b, hq, hkv, hd, hdv, total_q, (int)max_seqlen_q.value(), softmax_scale, causal,  \
3158	        softcap, win_l, win_r, s_aux_ptr, stream)
3159	    if (q.scalar_type() == at::kBFloat16) PF_RT(__nv_bfloat16, __nv_bfloat16, std::nullopt, std::nullopt, std::nullopt);
3160	    else if (q.scalar_type() == at::kHalf) PF_RT(__half, __half, std::nullopt, std::nullopt, std::nullopt);
3161	    else if (hd == 128 || hd == 256)  // native e4m3 wgmma prefill (2x tensor); hd256 uses CN=64/STAGES=2
3162	      pf::launch_prefill_fp8(q, k, v, out, lse, *cu_seqlens_q, cu_seqlens_k, seqused_k, page_table,
3163	        q_descale, k_descale, v_descale, b, hq, hkv, hd, hdv, total_q, (int)max_seqlen_q.value(),
3164	        softmax_scale, causal, softcap, win_l, win_r, stream);
3165	    else                                  PF_RT(__nv_fp8_e4m3, __nv_bfloat16, q_descale, k_descale, v_descale);
3166	#undef PF_RT
3167	  } else if (total_q > 0 && (can_decode_fast || pf_underfill)) {
3168	#define DS_DEC(TIN_, TC_, HD_, HDV_, QD_, KD_, VD_)                                                    \
3169	    launch_decode_split<TIN_, TC_, HD_, HDV_>(q, k, v, out, lse, *cu_seqlens_q, cu_seqlens_k, seqused_k, \
3170	        page_table, QD_, KD_, VD_, b, hq, hkv, total_q, max_q, max_klen, (int)num_splits, softmax_scale, \
3171	        causal, softcap, win_l, win_r, leftpad_ptr, stream)
3172	#define DS_RT(TIN_, TC_, QD_, KD_, VD_) do {                                                            \
3173	    if (hd == 128)                    DS_DEC(TIN_, TC_, 128, 128, QD_, KD_, VD_);                        \
3174	    else if (hd == 96)                DS_DEC(TIN_, TC_, 96, 96, QD_, KD_, VD_);                          \
3175	    else if (hd == 192 && hdv == 128) DS_DEC(TIN_, TC_, 192, 128, QD_, KD_, VD_);                       \
3176	    else if (hd == 192)               DS_DEC(TIN_, TC_, 192, 192, QD_, KD_, VD_);                       \
3177	    else if (hd == 256)               DS_DEC(TIN_, TC_, 256, 256, QD_, KD_, VD_);                       \
3178	    else                              DS_DEC(TIN_, TC_, 64, 64, QD_, KD_, VD_);                          \
3179	  } while (0)
3180	    if (q.scalar_type() == at::kBFloat16) DS_RT(__nv_bfloat16, __nv_bfloat16, std::nullopt, std::nullopt, std::nullopt);
3181	    else if (q.scalar_type() == at::kHalf) DS_RT(__half, __half, std::nullopt, std::nullopt, std::nullopt);
3182	    else if (hd == 128)  // native e4m3 wgmma decode-split (no convert pass)
3183	      launch_decode_split_fp8<128, 128>(q, k, v, out, lse, *cu_seqlens_q, cu_seqlens_k, seqused_k,
3184	        page_table, q_descale, k_descale, v_descale, b, hq, hkv, total_q, max_q, max_klen,
3185	        (int)num_splits, softmax_scale, causal, softcap, win_l, win_r, stream);
3186	    // hd64/hd96 fp8 decode: NATIVE fp8 wgmma via cp.async (no 128-wide TMA box, which would over-read a
3187	    // 64-wide head). The K/Q smem tiles are padded to HDQK=128 so koff8's row*128 swizzle stride fits;
3188	    // the QK still contracts only the real HD cols. No fp8->bf16 cast (the cast was LSU-bound at ~14us).
3189	    else if (hd == 64)
3190	      launch_decode_split_fp8<64, 64>(q, k, v, out, lse, *cu_seqlens_q, cu_seqlens_k, seqused_k,
3191	        page_table, q_descale, k_descale, v_descale, b, hq, hkv, total_q, max_q, max_klen,
3192	        (int)num_splits, softmax_scale, causal, softcap, win_l, win_r, stream);
3193	    else if (hd == 96)
3194	      launch_decode_split_fp8<96, 96>(q, k, v, out, lse, *cu_seqlens_q, cu_seqlens_k, seqused_k,
3195	        page_table, q_descale, k_descale, v_descale, b, hq, hkv, total_q, max_q, max_klen,
3196	        (int)num_splits, softmax_scale, causal, softcap, win_l, win_r, stream);
3197	    else if (hd == 256)   // native e4m3 hd256 decode-split (CN=64/STAGES=2, 2-box PV over HDV)
3198	      launch_decode_split_fp8<256, 256>(q, k, v, out, lse, *cu_seqlens_q, cu_seqlens_k, seqused_k,
3199	        page_table, q_descale, k_descale, v_descale, b, hq, hkv, total_q, max_q, max_klen,
3200	        (int)num_splits, softmax_scale, causal, softcap, win_l, win_r, stream);
3201	    else                                  DS_RT(__nv_fp8_e4m3, __nv_bfloat16, q_descale, k_descale, v_descale);
3202	#undef DS_RT
3203	#undef DS_DEC
3204	  } else if (total_q > 0) {
3205	    // The two wgmma paths above (split-KV decode for q<=4 & q*rep<=16; prefill for any other q>=1,
3206	    // softcap + sliding-window included) cover every q/rep/causal/window/softcap combination. Reaching
3207	    // here means the shape is outside the supported HEAD-DIM / DTYPE / LAYOUT envelope: hd==hdv in
3208	    // {64,96,128,192,256} (or 192/128 for decode), bf16/fp16/fp8-e4m3, contiguous head dim, hq%hkv==0.
3209	    TORCH_CHECK(false, "fa3-fwd: unsupported config (dtype=", q.scalar_type(), " hd=", hd, " hdv=", hdv,
3210	                " max_seqlen_q=", (max_seqlen_q.has_value() ? (int)max_seqlen_q.value() : -1),
3211	                " softcap=", softcap, " win=[", win_l, ",", win_r, "]); supported envelope: "
3212	                "hd==hdv in {64,96,128,192,256} (or 192/128 decode), bf16/fp16/fp8, contiguous, hq%hkv==0.");
3213	  }
3214	  // return [out, softmax_lse, out_accum(empty), softmax_lse_accum(empty)]
3215	  at::Tensor empty = at::empty({0}, q.options().dtype(at::kFloat));
3216	  return {out, lse, empty, empty};
3217	}
3218	
3219	at::Tensor mha_fwd_get_scheduler_metadata(
3220	    int64_t batch_size, int64_t max_seqlen_q, int64_t max_seqlen_k, int64_t num_heads, int64_t num_heads_k,
3221	    int64_t headdim, int64_t headdim_v, at::ScalarType qkv_dtype, at::Tensor seqused_k,
3222	    std::optional<at::Tensor> cu_seqlens_q, std::optional<at::Tensor> cu_seqlens_k, std::optional<at::Tensor> cu_seqlens_k_new,
3223	    std::optional<at::Tensor> seqused_q, std::optional<at::Tensor> leftpad_k, std::optional<int64_t> page_size,
3224	    int64_t max_seqlen_k_new, bool is_causal, int64_t window_size_left, int64_t window_size_right, bool has_softcap,
3225	    int64_t num_splits, std::optional<bool> pack_gqa, int64_t sm_margin) {
3226	  // Our fwd recomputes everything internally; return a benign tensor.
3227	  return at::zeros({1}, seqused_k.options().dtype(at::kInt));
3228	}
3229	
3230	TORCH_LIBRARY(FA3_LIB_NAME, m) {
3231	  m.def("fwd(Tensor! q, Tensor k, Tensor v, Tensor? k_new, Tensor? v_new, Tensor? q_v, "
3232	        "Tensor!? out, Tensor? cu_seqlens_q, Tensor? cu_seqlens_k, Tensor? cu_seqlens_k_new, "
3233	        "Tensor? seqused_q, Tensor? seqused_k, int? max_seqlen_q, int? max_seqlen_k, "
3234	        "Tensor? page_table, Tensor? kv_batch_idx, Tensor? leftpad_k, Tensor? rotary_cos, "
3235	        "Tensor? rotary_sin, Tensor? seqlens_rotary, Tensor? q_descale, Tensor? k_descale, "
3236	        "Tensor? v_descale, float softmax_scale, bool is_causal, int window_size_left, "
3237	        "int window_size_right, float softcap, bool is_rotary_interleaved, "
3238	        "Tensor? scheduler_metadata, int num_splits, bool? pack_gqa, int sm_margin, "
3239	        "Tensor? s_aux, int cp_world_size, int cp_rank, Tensor? cp_tot_seqused_k) -> Tensor[]");
3240	  m.impl("fwd", torch::kCUDA, &mha_fwd);
3241	  m.def("get_scheduler_metadata(int batch_size, int max_seqlen_q, int max_seqlen_k, "
3242	        "int num_heads, int num_heads_k, int headdim, int headdim_v, ScalarType qkv_dtype, "
3243	        "Tensor seqused_k, Tensor? cu_seqlens_q, Tensor? cu_seqlens_k, Tensor? cu_seqlens_k_new, "
3244	        "Tensor? seqused_q, Tensor? leftpad_k, int? page_size, int max_seqlen_k_new, "
3245	        "bool is_causal, int window_size_left, int window_size_right, bool has_softcap, "
3246	        "int num_splits, bool? pack_gqa, int sm_margin) -> Tensor");
3247	  m.impl("get_scheduler_metadata", torch::kCUDA, &mha_fwd_get_scheduler_metadata);
3248	}

