template <int CN, int CM, bool EXTRA>
__device__ __forceinline__ PfTile pf_work(
        int work, int tiles_m, int hkv, int rep,
        const int* __restrict__ cu_q, const int* __restrict__ cu_k, const int* __restrict__ seqused_k,
