1217	    const uint32_t sQ_wg = (uint32_t)__cvta_generic_to_shared(sQ) + (uint32_t)(cwg * 4096 * (int)sizeof(TC));
1218	    const uint32_t sK_a = (uint32_t)__cvta_generic_to_shared(sK0);
1219	    const uint32_t sV_a = (uint32_t)__cvta_generic_to_shared(sV0);
1220	    const uint32_t stK_bytes = (uint32_t)(KSTRIDE * (int)sizeof(TC));
1221	    const uint32_t stV_bytes = (uint32_t)(VSTRIDE * (int)sizeof(TC));
1222	
1223	    float acc_o[HDVsm / 2];
1224	#pragma unroll
1225	    for (int i = 0; i < HDVsm / 2; ++i) acc_o[i] = 0.f;
1226	    float m_r[2] = {-INFINITY, -INFINITY}, l_r[2] = {0.f, 0.f};
1227	    float s[CN / 2]; uint32_t P[CN / 4]; float sc[2];
1228	
1229	    // Break the ping-pong symmetry: WG0 pre-arrives its own scheduler barrier so it issues first.
1230	    if constexpr (PINGPONG) { if (cwg == 0) nb_arrive(PP_BASE, PP_CNT); }
1231	
1232	    while (!mbar_try_wait(&barQ[0], 0)) {}
1233	    asm volatile("fence.proxy.async.shared::cta;\n" ::: "memory");
1234	    while (!mbar_try_wait(&full[0], 0)) {}
1235	    // K/V TMA (cp.async.bulk) writes are made visible to the generic proxy (wgmma descriptor reads) by
1236	    // the mbarrier complete-tx mechanism itself, so the per-tile fence.proxy.async is redundant on the
1237	    // TMA path (matches CUTLASS's Hopper TMA pipeline, which fences once at prologue, not per tile). The
1238	    // non-TMA cp.async gather path keeps the explicit fence.
1239	    if constexpr (!USE_TMA) asm volatile("fence.proxy.async.shared::cta;\n" ::: "memory");
1240	#pragma unroll
1241	    for (int i = 0; i < CN / 2; ++i) s[i] = 0.f;
1242	    qk_gemm_g<TC, HD, CN, CM>(s, sQ_wg, sK_a);
1243	    if constexpr (EXTRA) { if (softcap > 0.f) pf_softcap<CN>(s, scale, softcap);
1244	                           pf_mask_win<CN>(s, n_lo * CN, qpos_lo, qpos_hi, seqlen_k, causal, win_l, win_r, tg, lpad); }
1245	    else                   pf_mask<CN>(s, n_lo * CN, qpos_lo, qpos_hi, seqlen_k, causal, tg);
1246	    sc[0] = softmax_stats<CN>(s, m_r, l_r, 0, 0, s2);
1247	    sc[1] = softmax_stats<CN>(s, m_r, l_r, 1, 0, s2);
1248	#pragma unroll
1249	    for (int i = 0; i < CN / 4; ++i) P[i] = pack_2x<TC>(s[2*i], s[2*i+1]);
1250	
1251	    for (int li = 1; li < n_cnt; ++li) {
1252	        const int nb = n_lo + li;
1253	        const int st = li % STAGES, pst = (li - 1) % STAGES;
1254	        const int fp = (li / STAGES) & 1;
1255	        while (!mbar_try_wait(&full[st], fp)) {}
1256	        if constexpr (!USE_TMA) asm volatile("fence.proxy.async.shared::cta;\n" ::: "memory");
1257	        if constexpr (PINGPONG) nb_sync(PP_BASE + cwg, PP_CNT);        // wait my turn to issue
1258	        qk_rs_pv_g<TC, HD, HDVsm, CN, CM>(s, acc_o, P, sQ_wg, sK_a + st * stK_bytes, sV_a + pst * stV_bytes, sc);
1259	        if constexpr (PINGPONG) nb_arrive(PP_BASE + (1 - cwg), PP_CNT); // release the other WG
1260	        wgmma_wait1();
1261	        if constexpr (EXTRA) { if (softcap > 0.f) pf_softcap<CN>(s, scale, softcap);
1262	                               pf_mask_win<CN>(s, nb * CN, qpos_lo, qpos_hi, seqlen_k, causal, win_l, win_r, tg, lpad); }
1263	        else                   pf_mask<CN>(s, nb * CN, qpos_lo, qpos_hi, seqlen_k, causal, tg);
1264	        sc[0] = softmax_stats<CN>(s, m_r, l_r, 0, li, s2);
1265	        sc[1] = softmax_stats<CN>(s, m_r, l_r, 1, li, s2);
1266	        wgmma_wait0();
1267	#pragma unroll
1268	        for (int i = 0; i < CN / 4; ++i) P[i] = pack_2x<TC>(s[2*i], s[2*i+1]);
1269	        mbar_arrive(&empty[pst]);
1270	    }
1271	    rescale_o_g(acc_o, sc);
1272	    pv_final_g<TC, HDVsm, CN>(acc_o, P, sV_a + ((n_cnt - 1) % STAGES) * stV_bytes);
1273	    mbar_arrive(&empty[(n_cnt - 1) % STAGES]);
1274	
1275	#pragma unroll
1276	    for (int r = 0; r < 2; ++r) {
1277	        l_r[r] = quad_sum(l_r[r]);
1278	        int idx = row0 + (r == 0 ? row_lo : row_hi);
1279	        bool val = idx < Mrows;
1280	        int token = idx / rep, qhead = hk * rep + idx % rep, qidx = q0 + token;
1281	        float mr = m_r[r];
1282	        // attention sink (s_aux): an extra per-head logit in the softmax DENOMINATOR (no value, so the
1283	        // numerator/acc_o is untouched). FA3 finalize_aux: sum += exp2(log2e*s_aux - max_scaled), with a
1284	        // fully-masked row clamping its max to 0. Only for the final (single-split) result.
1285	        if (s_aux != nullptr && num_splits <= 1) {
1286	            if (mr == -INFINITY) mr = 0.f;
1287	            l_r[r] += ex2_approx(float(M_LOG2E) * s_aux[qhead] - mr * s2);
1288	        }
1289	        bool bad = (l_r[r] == 0.f || l_r[r] != l_r[r]);
1290	        float inv = bad ? 0.f : 1.f / l_r[r];
1291	        const float invvd = inv * vd;                  // v_descale folds into the normalized output (fp8)
1292	        float lse_v = bad ? -INFINITY : mr * sc_eff + __logf(l_r[r]);
1293	        if (num_splits > 1) {
1294	            // write the NORMALIZED split partial (O_s, lse_s); combine_kernel does the cross-split reduce.
1295	            const int hq = hkv * rep;
1296	            float* op = Opart + (((long)split * total_q + qidx) * hq + qhead) * HDV;
1297	#pragma unroll
1298	            for (int c = 0; c < HDV / 8; ++c) {
1299	                int dv0 = 8 * c + 2 * tg;
1300	                if (val) { op[dv0] = acc_o[c*4+r*2+0] * invvd; op[dv0+1] = acc_o[c*4+r*2+1] * invvd; }
1301	            }
1302	            if (tg == 0 && val) LSEpart[((long)split * hq + qhead) * total_q + qidx] = lse_v;
1303	        } else {
1304	            long obase = (long)qidx * o_row + (long)qhead * o_head;
1305	#pragma unroll
1306	            for (int c = 0; c < HDV / 8; ++c) {
1307	                int dv0 = 8 * c + 2 * tg;
1308	                uint32_t o = pack_2x<TC>(acc_o[c*4+r*2+0] * invvd, acc_o[c*4+r*2+1] * invvd);
1309	                if (val) *reinterpret_cast<uint32_t*>(&O[obase + dv0]) = o;
1310	            }
1311	            if (tg == 0 && val) LSE[(long)qhead * total_q + qidx] = lse_v;
1312	        }
1313	    }
1314	}
