1628	// ===================== native fp8 (e4m3) prefill kernel =====================
1629	// Same warp-specialized shape as prefill_kernel (1 producer WG + 2 consumer WGs of 64 q-rows each)
1630	// but the matmuls run natively on the fp8 tensor core (~2x bf16). Q/K are stored as raw fp8 in the
1631	// 1-byte 128B-swizzle smem tile; V is transposed to the K-major [dv][key] tile the fp8 PV needs;
1632	// the softmax probabilities P are downcast to fp8 and round-tripped through smem so PV is an SS GEMM
1633	// (P and V both from smem descriptors -> no register-fragment puzzle). Output is bf16.
1634	template <int HD, int HDV, bool EXTRA, int STAGES, bool USE_TMA = false, int CN = CTA_N>
1635	__global__ __launch_bounds__(NThreads, 1) void prefill_fp8_kernel(
1636	        const __nv_fp8_e4m3* __restrict__ Q, const __nv_fp8_e4m3* __restrict__ K,
1637	        const __nv_fp8_e4m3* __restrict__ V, __nv_bfloat16* __restrict__ O, float* __restrict__ LSE,
1638	        const int* __restrict__ cu_q, const int* __restrict__ cu_k, const int* __restrict__ seqused_k,
1639	        const int* __restrict__ page_table,
1640	        long q_row, long q_head, long k_row, long k_head, long v_row, long v_head, long o_row, long o_head,
1641	        int hkv, int rep, int total_q, int block_size, int page_stride,
1642	        float scale, int causal, float softcap, int win_l, int win_r,
1643	        int num_splits, float* __restrict__ Opart, float* __restrict__ LSEpart,
1644	        const float* __restrict__ q_descale, const float* __restrict__ k_descale,
1645	        const float* __restrict__ v_descale, int ds_b, int ds_h,
1646	        const __grid_constant__ CUtensorMap mapK, const __grid_constant__ CUtensorMap mapVst) {
1647	    // K/Q smem are 128-wide regardless of HD: koff8 hardcodes a row*128 swizzle stride, so a 64-wide
1648	    // (hd64) tile would index past CTA_N*HD -> OOB. Allocate 128-wide (HDQK) so koff8 fits; the QK still
1649	    // contracts only the real HD cols (qk_fp8_ss<HD>), never reading the unused upper half.
1650	    constexpr int HDQK = (HD < 128) ? 128 : HD;
1651	    constexpr int KSTRIDE = CN * HDQK;         // one fp8 K tile (elems=bytes)
1652	    constexpr int VSTRIDE = HDV * 128;         // one transposed fp8 V tile (Vt is 128-key-padded, koff8R)
1653	    const int m_block = blockIdx.x / num_splits, split = blockIdx.x % num_splits, hk = blockIdx.y, bi = blockIdx.z;
1654	    const int q0 = cu_q[bi];
1655	    const int seqlen_q = cu_q[bi + 1] - q0;
1656	    const int seqlen_k = seqused_k ? seqused_k[bi] : (cu_k[bi + 1] - cu_k[bi]);
1657	    const int Mrows = seqlen_q * rep;
1658	    const int row0 = m_block * CTA_M;
1659	    if (row0 >= Mrows) return;                          // padded m_block: no valid rows
1660	    const int delta = seqlen_k - seqlen_q;
1661	    const long ds_idx = (long)bi * ds_b + (long)hk * ds_h;
1662	    const float qd = q_descale ? q_descale[ds_idx] : 1.f;
1663	    const float kd = k_descale ? k_descale[ds_idx] : 1.f;
1664	    const float vd = v_descale ? v_descale[ds_idx] : 1.f;
1665	    const float sc_eff = scale * qd * kd;
1666	    const float s2 = sc_eff * float(M_LOG2E);
1667	    const int top = (row0 + CTA_M - 1 < Mrows - 1) ? (row0 + CTA_M - 1) : (Mrows - 1);
1668	    const int qabs_max = (top / rep) + delta;
1669	    const int n_max = causal ? ((qabs_max + 1 + CN - 1) / CN) : ((seqlen_k + CN - 1) / CN);
1670	    // Empty CTA stamps -inf into its split-KV LSEpart rows (see emit_empty_lse) so LSEpart can be a
1671	    // plain at::empty; single-split exits. Detected uniformly, before the mbar_init/__syncthreads.
1672	    int n_lo = 0, n_cnt = n_max;
1673	    bool empty_cta = (seqlen_k <= 0) || (n_max <= 0);
1674	    if (!empty_cta && num_splits > 1) {
1675	        const int per = (n_max + num_splits - 1) / num_splits;
1676	        n_lo = split * per;
1677	        if (n_lo >= n_max) empty_cta = true;
1678	        else n_cnt = (n_max - n_lo < per) ? (n_max - n_lo) : per;
1679	    }
1680	    if (empty_cta) {
1681	        if (num_splits > 1)
1682	            emit_empty_lse(LSEpart, (int)threadIdx.x, split, hkv * rep, row0, Mrows, hk, rep, q0, total_q);
1683	        else
1684	            emit_zero_o<__nv_bfloat16, HDV>(O, LSE, (int)threadIdx.x, row0, Mrows, hk, rep, q0, total_q, o_row, o_head);
1685	        return;
1686	    }
1687	
1688	    constexpr int VstSTRIDE = CN * HDV;        // one PLAIN [key][dv] V staging tile (cp.async target)
1689	    __nv_fp8_e4m3* sQ = reinterpret_cast<__nv_fp8_e4m3*>(pf_smem);
1690	    __nv_fp8_e4m3* sK0 = sQ + CTA_M * HDQK;
1691	    __nv_fp8_e4m3* sV0 = sK0 + STAGES * KSTRIDE;
1692	    __nv_fp8_e4m3* sP  = sV0 + STAGES * VSTRIDE;
1693	    __nv_fp8_e4m3* sVst0 = sP + CTA_M * 128;   // sP is 128-key-padded (koff8R<CTA_M>, key<128)
1694	    uint64_t* bars = reinterpret_cast<uint64_t*>(sVst0 + STAGES * VstSTRIDE);
1695	    uint64_t* full = bars;                 // [STAGES] count NumProd  (K cp.async done + Vt transposed)
1696	    uint64_t* empty = bars + STAGES;       // [STAGES] count NumCons
1697	    uint64_t* loaded = bars + 2 * STAGES;  // [STAGES] count NumProd  (K + V-staging cp.async delivered)
1698	    uint64_t* barQ = bars + 3 * STAGES;    // [1] count NumProd
1699	
1700	    const int tid = threadIdx.x;
1701	    if (tid == 0) {
1702	#pragma unroll
1703	        for (int s = 0; s < STAGES; ++s) { mbar_init(&full[s], NumProd); mbar_init(&empty[s], NumCons); mbar_init(&loaded[s], USE_TMA ? 1 : NumProd); }
1704	        mbar_init(&barQ[0], NumProd);
1705	    }
1706	    __syncthreads();
1707	
1708	    const int wg = tid / WG;
1709	    if (wg == 0) {
1710	        // ---------- producer: cp.async Q/K (swizzled) + V (plain staging), then transpose V into sVt ----
1711	        // cp.async lets the producer race STAGES ahead instead of blocking per-LDG. K/Q stream straight
1712	        // into the swizzled wgmma tiles; V can't be transposed by cp.async so it lands in a plain [key][dv]
1713	        // staging ring (loaded[]) and a pipelined in-smem pass transposes it into the K-major sVt (full[]).
1714	        producer_regs();
1715	        const int pt = tid;
1716	        const int idx = row0 + pt;
1717	        const bool qval = idx < Mrows;
1718	        const int token = qval ? idx / rep : 0;
1719	        const int qhead = hk * rep + (qval ? idx % rep : 0);
1720	        const __nv_fp8_e4m3* qsrc = Q + (long)(q0 + token) * q_row + (long)qhead * q_head;
1721	        gather_row_k8_cp<HD>(sQ, (uint32_t)__cvta_generic_to_shared(sQ), pt, qsrc, qval);
1722	        cp_async_mbar_arrive(&barQ[0]);
1723	        const uint32_t sVst_a = (uint32_t)__cvta_generic_to_shared(sVst0);
1724	        // Issue loads for tile `li` into stage st (K -> swizzled sK, V -> plain staging). USE_TMA path:
1725	        // pt==0 issues TMA boxes (paged: CN/block_size page boxes at page-table rows; contiguous: 1 box),
1726	        // delivered against loaded[st] (one expect_tx covers K+Vst). Else: per-key cp.async gather.
1727	        const int xk_tma = hk * HD, xv_tma = hk * HDV;
1728	        const int last_pg = page_table ? ((seqlen_k - 1) / block_size) : 0;
1729	        const long ybase_tma = (long)(cu_k ? cu_k[bi] : 0);
1730	        auto issue_load = [&](int li) {
1731	            const int st = li % STAGES;
1732	            if (li >= STAGES) { int ep = ((li / STAGES) - 1) & 1; while (!mbar_try_wait(&empty[st], ep)) {} }
1733	            const int nb = n_lo + li;
1734	            if constexpr (USE_TMA) {
1735	                if (pt == 0) {
1736	                    mbar_expect_tx(&loaded[st], (uint32_t)((CTA_N * HD + CTA_N * HDV)));
1737	                    __nv_fp8_e4m3* sKp = sK0 + st * KSTRIDE;
1738	                    __nv_fp8_e4m3* sVstp = sVst0 + st * VstSTRIDE;
1739	                    if (page_table) {
1740	                        const int pages = CTA_N / block_size;
1741	                        for (int p = 0; p < pages; ++p) {
1742	                            int pg = nb * pages + p; if (pg > last_pg) pg = last_pg;
1743	                            int yrow = page_table[(long)bi * page_stride + pg] * block_size;
1744	                            int boff = p * block_size * 128;
1745	                            tma_box(sKp + boff, &mapK, xk_tma, yrow, &loaded[st]);
1746	                            tma_box(sVstp + boff, &mapVst, xv_tma, yrow, &loaded[st]);
1747	                        }
1748	                    } else {
1749	                        int yk = (int)ybase_tma + nb * CTA_N;
1750	                        tma_box(sKp, &mapK, xk_tma, yk, &loaded[st]);
1751	                        tma_box(sVstp, &mapVst, xv_tma, yk, &loaded[st]);
1752	                    }
1753	                }
1754	                return;
1755	            }
1756	            // CN keys per tile (CN<=WG): only the first CN producer lanes own a key row; the rest just
1757	            // arrive on loaded[] (inited NumProd). koff8R<CN> for the CN-row K tile (hd256 spans 2 col-blocks).
1758	            const int key = nb * CN + pt;
1759	            const bool kval = (pt < CN) && (key < seqlen_k);
1760	            if (pt < CN) {
1761	                long krow;
1762	                if (page_table) {
1763	                    int blk = kval ? page_table[(long)bi * page_stride + key / block_size] : 0;
1764	                    krow = (long)blk * block_size + (kval ? (key % block_size) : 0);
1765	                } else {
1766	                    krow = (long)(cu_k ? cu_k[bi] : 0) + (kval ? key : 0);
1767	                }
1768	                const __nv_fp8_e4m3* ksrc = K + krow * k_row + (long)hk * k_head;
1769	                const __nv_fp8_e4m3* vsrc = V + krow * v_row + (long)hk * v_head;
1770	                __nv_fp8_e4m3* sKp = sK0 + st * KSTRIDE;
1771	                __nv_fp8_e4m3* sVstp = sVst0 + st * VstSTRIDE;
1772	                gather_row_k8_cp<HD, CN>(sKp, (uint32_t)__cvta_generic_to_shared(sKp), pt, ksrc, kval);
1773	                gather_row_plain8_cp<HDV>(sVstp, sVst_a + (uint32_t)(st * VstSTRIDE), pt, vsrc, kval);
1774	            }
