1787	    }
1788	
1789	    // ---------- consumers ----------
1790	    consumer_regs();
1791	    const int cwg = wg - 1;
1792	    const int wtid = tid % WG, warp = wtid >> 5, lane = wtid & 31;
1793	    const int group = lane >> 2, tg = lane & 3;
1794	    const int row_lo = cwg * 64 + warp * 16 + group, row_hi = row_lo + 8;
1795	    const int qpos_lo = ((row0 + row_lo) / rep) + delta, qpos_hi = ((row0 + row_hi) / rep) + delta;
1796	    const uint32_t sQ_wg = (uint32_t)__cvta_generic_to_shared(sQ) + (uint32_t)(cwg * 8192);
1797	    const uint32_t sK_a = (uint32_t)__cvta_generic_to_shared(sK0);
