2264	template <typename TIn, typename TC>
2265	static void launch_prefill(const at::Tensor& q, const at::Tensor& k, const at::Tensor& v,
2266	                           at::Tensor& out, at::Tensor& lse, const at::Tensor& cu_q,
2267	                           const std::optional<at::Tensor>& cu_k, const std::optional<at::Tensor>& seqused_k,
2268	                           const std::optional<at::Tensor>& page_table,
2269	                           const std::optional<at::Tensor>& qd_, const std::optional<at::Tensor>& kd_,
2270	                           const std::optional<at::Tensor>& vd_,
2271	                           int b, int hq, int hkv, int hd, int hdv, int total_q, int max_seqlen_q,
2272	                           double scale, bool causal, double softcap, int win_l, int win_r,
2273	                           const float* s_aux, cudaStream_t stream) {
2274	    const bool paged = page_table.has_value();
2275	    int rep = hq / hkv;
2276	    long q_row = q.stride(0), q_head = q.stride(1);
2277	    long k_row, k_head, v_row, v_head;
2278	    if (paged) { k_row = k.stride(1); k_head = k.stride(2); v_row = v.stride(1); v_head = v.stride(2); }
2279	    else       { k_row = k.stride(0); k_head = k.stride(1); v_row = v.stride(0); v_head = v.stride(1); }
2280	    long o_row = out.stride(0), o_head = out.stride(1);
2281	    int block_size = paged ? (int)k.size(1) : 0;
2282	    int page_stride = paged ? (int)page_table->stride(0) : 0;
2283	    int tiles_m = (max_seqlen_q * rep + CTA_M - 1) / CTA_M;
2284	    const float* qd = qd_ ? (const float*)qd_->data_ptr() : nullptr;
2285	    const float* kd = kd_ ? (const float*)kd_->data_ptr() : nullptr;
2286	    const float* vd = vd_ ? (const float*)vd_->data_ptr() : nullptr;
2287	    int ds_b = qd_ ? (int)qd_->stride(0) : 0, ds_h = qd_ ? (int)qd_->stride(1) : 0;
2288	
2289	    // TMA-paged loader: requires paged KV with a swizzle-composable page (block_size | CTA_N and a
2290	    // multiple of 8 so per-page boxes land at the right swizzle phase) and a contiguous [.,hkv*hd]
2291	    // row stride. Disabled for fp8 (TIn!=TC ⇒ producer must convert, TMA copies raw bytes).
2292	    // TMA needs 64-col-aligned per-page boxes (KBOX=HD/64); head dims that aren't a multiple of 64
2293	    // (e.g. 96, padded to 128 in smem) can't tile cleanly -> fall back to the cp.async gather. The
2294	    // key tile CN need NOT be a 64-multiple: pages of [block_size,64] boxes stack at row offsets
2295	    // p*block_size inside a CN-row col-block, so CN%block_size==0 (block_size%8==0) suffices -- BUT the
2296	    // contiguous one-[CN,64]-box path needs CN to compose byte-exactly with the 128B swizzle, which only
