200	__device__ __forceinline__ float quad_max(float v) {
201	    v = fmaxf(v, __shfl_xor_sync(0xffffffffu, v, 1));
202	    v = fmaxf(v, __shfl_xor_sync(0xffffffffu, v, 2));
203	    return v;
204	}
205	__device__ __forceinline__ float quad_sum(float v) {
206	    v += __shfl_xor_sync(0xffffffffu, v, 1);
207	    v += __shfl_xor_sync(0xffffffffu, v, 2);
208	    return v;
209	}
210	__device__ __forceinline__ uint32_t pack_bf16(float lo, float hi) {
211	    __nv_bfloat16 a = __float2bfloat16_rn(lo), b = __float2bfloat16_rn(hi);
212	    uint16_t ua, ub; memcpy(&ua, &a, 2); memcpy(&ub, &b, 2);
213	    return uint32_t(ua) | (uint32_t(ub) << 16);
214	}
215	// Pack two fp32 into the wgmma A/B register pair for the QKV element type T (bf16 or fp16). Both
216	// are 16-bit so the smem/swizzle layout is byte-identical; only the wgmma type token and pack differ.
217	template <typename T> __device__ __forceinline__ uint32_t pack_2x(float lo, float hi);
218	template <> __device__ __forceinline__ uint32_t pack_2x<__nv_bfloat16>(float lo, float hi) { return pack_bf16(lo, hi); }
219	template <> __device__ __forceinline__ uint32_t pack_2x<__half>(float lo, float hi) {
220	    __half a = __float2half_rn(lo), b = __float2half_rn(hi);
221	    uint16_t ua, ub; memcpy(&ua, &a, 2); memcpy(&ub, &b, 2);
222	    return uint32_t(ua) | (uint32_t(ub) << 16);
223	}
