if constexpr (COOP) {
    constexpr int TPR = HD / 8;          // consecutive lanes cooperating per row (16 for hd128)
    constexpr int RPP = WG / TPR;        // rows resolved per producer pass (8 for hd128)
    static_assert(CN % RPP == 0, "COOP gather requires RPP | CN");
    constexpr int RPT = CN / RPP;        // rows each lane strides over (also page entries/lane)
    const int col_th = pt % TPR;         // 0..TPR-1 -> this lane's 16B head-dim chunk
    const int rowsub = pt / TPR;         // 0..RPP-1 -> this lane's row within a pass
    const int col = col_th * 8;          // head-dim ELEMENT offset of this lane's chunk
    const int rsw = (pt & 31) / TPR;     // rowsub within warp (shfl source-lane base)
    const int kbase = (int)(cu_k ? cu_k[bi] : 0);
    // BARRIER-FREE paged gather (matches FA3 PagedKVManager): each lane loads ONE page_table
    // entry (spread across all 128 lanes -> the RPT lookups issue in PARALLEL, one LDG deep) and
    // __shfl broadcasts each physical row to the TPR lanes that cooperate on it. Removing the old
    // 2-pass smem-prefetch + per-tile producer-WG bar.sync lets the producer race STAGES ahead so
    // a future tile's page LDG overlaps the current tile's cp.async. (A prior attempt CONCENTRATED
    // the lookups on col_th==0 and serialized the whole warp on one lane -> 2x slower; the fix is
    // the FA3 spread: lane col_th==r of a row-group owns row rowsub+r*RPP's page entry.)
    for (int li = 0; li < n_cnt; ++li) {
        const int nb = n_lo + li;
        const int st = li % STAGES;
        if (li >= STAGES) { int ep = ((li / STAGES) - 1) & 1; while (!mbar_try_wait(&empty[st], ep)) {} }
        int ent = -1;                    // this lane's resolved physical row (for row rowsub+col_th*RPP)
        if (col_th < RPT) {
            const int key = nb * CN + rowsub + col_th * RPP;
            const bool kv = key < seqlen_k;
            if (page_table) {
                int blk = kv ? page_table[(long)bi * page_stride + key / block_size] : -1;
                ent = kv ? blk * block_size + (key % block_size) : -1;
            } else {
                ent = kv ? kbase + key : -1;
            }
        }
        TC* sKp = sK0 + st * KSTRIDE; TC* sVp = sV0 + st * VSTRIDE;
        const uint32_t sKa = (uint32_t)__cvta_generic_to_shared(sKp);
        const uint32_t sVa = (uint32_t)__cvta_generic_to_shared(sVp);
        #pragma unroll
        for (int r = 0; r < RPT; ++r) {
            const int row = rowsub + r * RPP;
            const long krow = __shfl_sync(0xffffffffu, ent, rsw * TPR + r, 32);
            const int ok = koffR<CN>(row, col), ov = voffR<CN>(row, col);
            if (krow >= 0) {
                cp_async_16(sKa + (uint32_t)(ok * 2), K + krow * k_row + (long)hk * k_head + col);
                cp_async_16(sVa + (uint32_t)(ov * 2), V + krow * v_row + (long)hk * v_head + col);
            } else {
                *reinterpret_cast<uint4*>(sKp + ok) = make_uint4(0, 0, 0, 0);
                *reinterpret_cast<uint4*>(sVp + ov) = make_uint4(0, 0, 0, 0);
            }
        }
        PF_PUBLISH(&full[st]);           // COOP implies !CONV (is_same<TIn,TC>)
    }
    return;
}

