/******************************************************************************
 * Copyright (c) 2024, Jay Shah, Ganesh Bikshandi, Ying Zhang, Vijay Thakkar, Pradeep Ramani, Tri Dao.
 ******************************************************************************/

#pragma once

#include <tuple>

// Return {kBlockM, kBlockN, MmaPV_is_RS, IntraWGOverlap}
constexpr std::tuple<int, int, bool, bool> tile_size_fwd_sm90(
        int headdim, int headdim_v, bool is_causal, bool is_local, int element_size=2,
        bool v_colmajor=false, bool paged_kv_non_TMA=false, bool softcap=false, bool use_one_mma_wg=false) {
    if (element_size == 2) {
        if (headdim <= 64) {
            // return {same_hdim ? 192 : 64, same_hdim ? 128 : 64, same_hdim, same_hdim};
            // With this workaround in Cutlass 3.8, tile size 192 x 128 got slower for non-causal, idk why
            // https://github.com/NVIDIA/cutlass/blob/833f6990e031b48b4cd2fcf55e0849c51ef6bac2/include/cute/container/tuple.hpp#L131
            if (headdim_v == 512) {
                return {64, 64, false, false};
            } else if (headdim_v == 256) {
                return {128, 96, true, false};
            } else {
                if (use_one_mma_wg) {
                    return {64, 192, true, true};
                } else {
                    // Switch to tile size 192 x 192 for now
                    // bool const use_blockN_128 = is_causal || is_local;
                    // return {192, use_blockN_128 ? 128 : 192, use_blockN_128, true}; // BASE
                    // Benefits SWA when window length <= 128
                    return {192, is_causal ? 128 : is_local || paged_kv_non_TMA ? 160 : 192, is_causal || is_local, !is_local};
                    // return {192, is_causal ? 128 : 160, true, !is_local};
                    // return {128, use_blockN_128 ? 160 : 192, use_blockN_128, !use_blockN_128};
                    // return {192, is_local ? 160 : 192, true, false};
                }
            }
            // Good for long seqlen (>= 4k) but suffers from tile quantization at short seqlen
            // return {192, is_causal || is_local ? 192 : 176, true, false};
        } else if (headdim <= 96) {
            return {192, is_local || paged_kv_non_TMA ? 128 : 144, false, true};
        } else if (headdim <= 128) {
            if (use_one_mma_wg) {
                return {64, is_causal || is_local || paged_kv_non_TMA ? 128 : 176, true, true};
            } else {
                return {128, is_causal || is_local || paged_kv_non_TMA ? 128 : 160, true, true};
            }
            // {128, 192, false, false} and {192, 128, false, true} are quite good too
            // 128 x 192 hits the limit of smem if MmaPV_is_RS, 128 x 144 hits the limit if !MmaPV_is_RS
        } else if (headdim <= 192) {
            return {128, paged_kv_non_TMA || is_local ? 96 : (headdim_v <= 128 ? 128 : 96), true, true};  // 128 x 112 hits the limit of smem
        } else {
            return {128, is_local ? 64 : 80, true, true};  // 128 x 80 hits the limit of smem
        }
    } else {
        // FP8 path
        if (use_one_mma_wg) {
            // Decode tiles — independent of two-level accumulation setting
            if (headdim <= 96) {
                return {64, 128, true, true};
            } else {
                return {64, 96, true, true};
            }
        } else {
            // Prefill tiles — two-level accumulation needs smaller tiles to reduce
            // register pressure from the separate fp32 accumulator (tOrO_accum).
            // Currently just optimized for causal case.
#ifndef FLASHATTENTION_DISABLE_FP8_TWO_LEVEL_ACCUMULATION
            if (headdim <= 64) {
                return {192, 128, true, true};
            } else if (headdim <= 96) {
                return {128, 128, true, true};
            } else if (headdim <= 128) {
                return {128, 192, true, true};
            } else if (headdim <= 192) {
                return {128, 96, true, true};
            } else {
                return {128, is_local ? 64 : 128, true, !paged_kv_non_TMA};  // TODO: FP8 prefill ~0.54x of BF16 with two-level accum at hd256
            }
#else
            if (headdim <= 64) {
                return {192, 160, true, true};
            } else if (headdim <= 96) {
                return {192, 128, true, true};
            } else if (headdim <= 128) {
                return {128, paged_kv_non_TMA ? 160 : (v_colmajor || (softcap && is_local) ? 192 : 224), true, true};
            } else if (headdim <= 192) {
                return {128, (paged_kv_non_TMA || softcap) && is_local ? 128 : 160, true, true};
            } else {
                return {128, is_local ? 64 : 128, true, !paged_kv_non_TMA};
            }
#endif
        }
    }
}

// Return {kBlockM, kBlockN, kNWarps, kStages, Q_in_regs}

