// PV with P in REGISTERS (RS A operand): acc_o += P.V over CTA_N keys, A = P16[4kb..4kb+3] per k-block,
// B = Vt[dv][key] (smem descriptor). No smem-P scatter/barrier -> enables the QK(i+1)/PV(i) pipeline.
// m64n128 for HDV=128, m64n64 for HDV=64 (acc_o[32]).
template <int HDV>
__device__ __forceinline__ void pv_fp8_rs(float (&acc_o)[HDV/2], const uint32_t (&P16)[16], uint32_t sV_base) {
    asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");
#pragma unroll
    for (int kb = 0; kb < CTA_N / 32; ++kb) {
        uint32_t off = (uint32_t)(kb * 32);
        uint64_t dB = make_smem_desc(sV_base + off, SW8_LBO, SW8_SBO, 1);
        if constexpr (HDV == 128)
            asm volatile(
            "{\n.reg .pred p;\n setp.ne.b32 p, %68, 0;\n"
            "wgmma.mma_async.sync.aligned.m64n128k32.f32.e4m3.e4m3 " PF_ACC64 ",{%64,%65,%66,%67},%69,p,%70,%71;\n}\n"
            : PF_OUT64(acc_o)
            : "r"(P16[kb*4+0]),"r"(P16[kb*4+1]),"r"(P16[kb*4+2]),"r"(P16[kb*4+3]),
              "r"(1),"l"(dB),"n"(1),"n"(1));
        else
            asm volatile(
            "{\n.reg .pred p;\n setp.ne.b32 p, %36, 0;\n"
            "wgmma.mma_async.sync.aligned.m64n64k32.f32.e4m3.e4m3 " PF_ACC32 ",{%32,%33,%34,%35},%37,p,%38,%39;\n}\n"
            : PF_OUT32(acc_o, 0)
            : "r"(P16[kb*4+0]),"r"(P16[kb*4+1]),"r"(P16[kb*4+2]),"r"(P16[kb*4+3]),
              "r"(1),"l"(dB),"n"(1),"n"(1));
    }
    asm volatile("wgmma.commit_group.sync.aligned;\n" ::: "memory");
}

