// Blocking mbarrier wait that PARKS the warp on a miss (HW suspend up to ~10ms via the try_wait
// suspend-time operand) instead of hot-spinning `while(!mbar_try_wait){}`. Matches FA3/CUTLASS's
// consumer_wait (test_wait probe, then a parking try_wait). The hot spin keeps issuing try_wait+branch,
// stealing issue slots from the sibling math warpgroup at 1 CTA/SM -> tensor pipe starved (ncu: paged
// prefill 61% tensor, barrier-stall 0.73, long_scoreboard 0.37 because we never park). Parking frees
// those slots (FA3: 75% tensor, barrier 0.44, loads move to long_scoreboard 1.14). Correctness identical.
__device__ __forceinline__ void mbar_wait(uint64_t* bar, int phase) {
    uint32_t a = (uint32_t)__cvta_generic_to_shared(bar);
    asm volatile("{\n.reg .pred p;\n"
                 "mbarrier.test_wait.parity.shared::cta.b64 p, [%0], %1;\n"
                 "@p bra DONE%=;\n"
                 "WAIT%=:\n"
                 "mbarrier.try_wait.parity.shared::cta.b64 p, [%0], %1, %2;\n"
                 "@p bra DONE%=;\n"
                 "bra WAIT%=;\n"
                 "DONE%=:\n}\n" :: "r"(a), "r"(phase), "r"(0x989680) : "memory");
}

