__device__ __forceinline__ void pv_boxes(float (&acc_o)[HDV/2], const uint32_t (&P)[CN/4], uint32_t sV_base) {
    constexpr uint32_t LBO = (uint32_t)(CN * 128), BOX = (uint32_t)(CN * 128);
    // ONE wgmma group for the whole PV (all HDV/64 boxes): single fence, all boxes, single commit. The
    // boxes write disjoint acc lanes so they batch freely; keeping them in one group means wgmma_wait1
    // (after the next QK) leaves the FULL PV in flight to overlap the softmax (FA3-style QK/PV pipeline).
    asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");
    pv_box64_body<T, 0, HDV/2, CN>(acc_o, P, make_smem_desc(sV_base, LBO, SW_V_SBO, 1));
    if constexpr (HDV >= 128) pv_box64_body<T, 32, HDV/2, CN>(acc_o, P, make_smem_desc(sV_base + 1*BOX, LBO, SW_V_SBO, 1));
    if constexpr (HDV >= 192) pv_box64_body<T, 64, HDV/2, CN>(acc_o, P, make_smem_desc(sV_base + 2*BOX, LBO, SW_V_SBO, 1));
    if constexpr (HDV >= 256) pv_box64_body<T, 96, HDV/2, CN>(acc_o, P, make_smem_desc(sV_base + 3*BOX, LBO, SW_V_SBO, 1));
    asm volatile("wgmma.commit_group.sync.aligned;\n" ::: "memory");
}
