// PARKING wait for the PRODUCER's empty[] backpressure only: in compute-bound prefill the (fast) gather
// producer fills the STAGES ring then hot-spins on empty[] (ncu: producer NOT load-bound, long_scoreboard
// 0.37, but barrier-stall high) -- that spin burns warp-scheduler issue slots that the compute-bound
// consumer needs. Parking (3-operand try_wait.parity suspend) frees those slots. The producer is ahead of
// the consumer, so its wake latency is off the critical path (unlike the consumer's full[] wait, which
// must wake immediately -- parking THAT regressed). FA3's producer is load-bound (long_scoreboard 1.14)
// so it never hot-spins empty[]; this recovers the same effect faithfully.
__device__ __forceinline__ void mbar_wait(uint64_t* bar, int phase) {
    uint32_t a = (uint32_t)__cvta_generic_to_shared(bar);
    asm volatile("{\n.reg .pred p;\n"
                 "mbarrier.test_wait.parity.shared::cta.b64 p, [%0], %1;\n"
                 "@p bra DONE%=;\n"
                 "WAIT%=:\n"
                 "mbarrier.try_wait.parity.shared::cta.b64 p, [%0], %1, %2;\n"
                 "@p bra DONE%=;\n"
                 "bra WAIT%=;\n"
                 "DONE%=:\n}\n" :: "r"(a), "r"(phase), "r"(0x989680) : "memory");
}

