         else      { if (extra) DS_BY_TMA(true, DCN_W, DST_W, DCM_W, 1, NS_, OP_, LP_); else DS_BY_TMA(false, DCN_W, DST_W, DCM_W, 1, NS_, OP_, LP_); } } while (0)

