        sc[1] = softmax_stats<CN>(s, m_r, l_r, 1, li, s2);
        wgmma_wait0();
        rescale_o_g(acc_o, sc);                                        // rescale O AFTER PV, to the new max
#pragma unroll
        for (int i = 0; i < CN / 4; ++i) P[i] = pack_2x<TC>(s[2*i], s[2*i+1]);
        mbar_arrive(&empty[pst]);
    }
