    pv_final_g<TC, HDVsm, CN>(acc_o, P, sV_a + ((n_cnt - 1) % STAGES) * stV_bytes);
    mbar_arrive(&empty[(n_cnt - 1) % STAGES]);

#pragma unroll
    for (int r = 0; r < 2; ++r) {
        l_r[r] = quad_sum(l_r[r]);
        int idx = row0 + (r == 0 ? row_lo : row_hi);
        bool val = idx < Mrows;
        int token = idx / rep, qhead = hk * rep + idx % rep, qidx = q0 + token;
        float mr = m_r[r];
