struct PfTile {
    bool valid;
    int q0, hk, bi, seqlen_q, seqlen_k, Mrows, row0, delta, n_lo, n_cnt;
    float sc_eff, s2, vd;
};
template <int CN, int CM, bool EXTRA>
__device__ __forceinline__ PfTile pf_work(
        int work, int tiles_m, int hkv, int rep, int batch,
        const int* __restrict__ cu_q, const int* __restrict__ cu_k, const int* __restrict__ seqused_k,
        int causal, int win_l, int win_r, float scale,
        const float* __restrict__ q_descale, const float* __restrict__ k_descale,
        const float* __restrict__ v_descale, int ds_b, int ds_h) {
    PfTile t; t.valid = false;
    int bi, m_block;
    if (causal) {
        // GLOBAL LPT (FA3 DynamicPersistentTileScheduler): m_block varies SLOWEST so the heaviest causal
        // tiles across ALL heads/batches are handed out first and the lightest (m_block=0) drain the tail
        // -> makespan overhang ~= one light tile. Per-head LPT stranded the LAST head's full-width heavy
        // tile at the global tail (one CTA busy while ~131 idle; ncu large4k 58% SM vs seq16k 73%).
        const int nhb = hkv * batch;
        const int m_local = work / nhb;
        const int hbrem = work - m_local * nhb;
        bi = hbrem / hkv;
        t.hk = hbrem - bi * hkv;
        m_block = (tiles_m - 1) - m_local;
    } else {
        // non-causal: all m_blocks are equal work -> ordering is irrelevant; keep the per-head mapping.
        const int hb = tiles_m * hkv;
        bi = work / hb;
        const int rem = work - bi * hb;
        t.hk = rem / tiles_m;
        m_block = (tiles_m - 1) - (rem - t.hk * tiles_m);
    }
    t.bi = bi;

