# 2) insert pv_box256_body right before rescale_o_g template
box256='''// One 256-col PV output box: (CN/16)x m64n256k16 RS wgmma into acc[0..127] (the full hd256 acc_o).
// A=P (regs, K-major), B=V (MN-major, transB=1). The single m64n256 walks the 4 dv-blocks at 0,LBO,2LBO,
// 3LBO (LBO==CN*128==dv-block stride), exactly the 2x-m64n128 layout -> HALF the PV wgmma of the 2-box
// form (matches FA3 TiledMmaPV's single SM90_64x256x16_RS), denser tensor feed. acc reg->(dv,row) map is
// the concatenation of the two n128 blocks (verified vs the 2-box epilogue by the correctness gate).
template <typename T, int N, int CN>
__device__ __forceinline__ void pv_box256_body(float (&acc)[N], const uint32_t (&P)[CN/4], uint64_t baseV) {
#pragma unroll
    for (int kb = 0; kb < CN / 16; ++kb) {
        uint64_t dB = desc_add(baseV, (uint32_t)v_doff(kb));
        if constexpr (is_f16<T>())
            asm volatile(
            "{\\n.reg .pred p;\\n setp.ne.b32 p, %133, 0;\\n"
            "wgmma.mma_async.sync.aligned.m64n256k16.f32.f16.f16 " PF_ACC128 ",{%128,%129,%130,%131},%132,p,%134,%135,%136;\\n}\\n"
            : PF_OUT128(acc)
            : "r"(P[kb*4+0]),"r"(P[kb*4+1]),"r"(P[kb*4+2]),"r"(P[kb*4+3]),"l"(dB),"r"(1),"n"(1),"n"(1),"n"(1));
        else
            asm volatile(
            "{\\n.reg .pred p;\\n setp.ne.b32 p, %133, 0;\\n"
            "wgmma.mma_async.sync.aligned.m64n256k16.f32.bf16.bf16 " PF_ACC128 ",{%128,%129,%130,%131},%132,p,%134,%135,%136;\\n}\\n"
            : PF_OUT128(acc)
            : "r"(P[kb*4+0]),"r"(P[kb*4+1]),"r"(P[kb*4+2]),"r"(P[kb*4+3]),"l"(dB),"r"(1),"n"(1),"n"(1),"n"(1));
    }
}
'''
