                   (k.stride(0) == (int64_t)block_size * k.stride(1)) &&
                   (v.stride(0) == (int64_t)block_size * v.stride(1)) &&
                   k.stride(3) == 1 && v.stride(3) == 1;
    // TMA-contiguous loader (non-paged dense/varlen): a 2D map over [hkv*hd, total_k] feeds the wgmma
