                asm volatile("{\n.reg .pred p;\n setp.ne.b32 p, %50, 0;\n"
                "wgmma.mma_async.sync.aligned.m64n96k16.f32.bf16.bf16 " PF_ACC48 ",%48,%49,p,%51,%52,%53,%54;\n}\n"
                : PF_OUT48(s) : "l"(dA),"l"(dB),"r"(scaleD),"n"(1),"n"(1),"n"(0),"n"(0));
