2463	                             at::Tensor& out, at::Tensor& lse, const at::Tensor& cu_q,
2464	                             const std::optional<at::Tensor>& cu_k, const std::optional<at::Tensor>& seqused_k,
2465	                             const std::optional<at::Tensor>& page_table, const CUtensorMap& mapK,
2466	                             const CUtensorMap& mapV, int hkv, int rep, int total_q, int block_size,
2467	                             int page_stride, int tiles_m, int b, double scale, bool causal,
2468	                             double softcap, int win_l, int win_r,
2469	                             long q_row, long q_head, long k_row, long k_head, long v_row, long v_head,
2470	                             long o_row, long o_head, int num_splits, float* Opart, float* LSEpart,
