2472	                             const float* s_aux, const int* leftpad_k,
2473	                             cudaStream_t stream) {
2474	    const bool paged = page_table.has_value();
2475	    constexpr int HDsm = ((HD + 63) / 64) * 64, HDVsm = ((HDV + 63) / 64) * 64;
2476	    constexpr int NTHR = WG * (1 + CM / 64);   // 1 producer WG + CM/64 consumer WGs
2477	
2478	    // Persistent continuous-ring prefill: collapses the per-tile grid's ~8.7 waves into 1 (recovering
2479	    // the 14%->18.7% inter-wave SM-residency gap that bounds the big-head / long-context dense configs).
2480	    // The lever that makes it WIN (vs the earlier single/double-Q gather attempts that regressed): Q is
2481	    // reloaded per item via ONE async TMA (rep==1 contiguous), fast enough that the STAGES-deep K/V ring
2482	    // hides it -> single-Q fits the full ring (no double-Q smem squeeze that forced STAGES=2 and starved
2483	    // the pipe). Scoped to rep==1 + contiguous Q/KV: the rep>1 cp.async-gather Q reload serializes on the
2484	    // single-Q handshake and lost to the per-tile grid (gqa 0.82->0.78, mqa 0.82->0.77), so GQA/MQA/
2485	    // paged/varlen stay on the per-tile grid.
2486	    constexpr int PSTAGES = STAGES;
2487	    constexpr bool PF_PERSIST = true;
2488	    // CM==64 persist is enabled ONLY for big heads (HD>=192): the hd256 dense-prefill wide-CN path uses
2489	    // a half-height Q tile so a wider K/V tile fits at STAGES=3 (the ping-pong is off for HD>128 anyway).
2490	    // Scoping to HD>=192 keeps the CM=64 decode-split path (hd<=128, which also calls launch_prefill_t)
2491	    // on its per-tile grid -- only the non-paged single-split big-head prefill reaches this branch.
2492	    if constexpr (PF_PERSIST && (CM == 128 || (CM == 64 && HD >= 192)) && TMA && std::is_same<TIn, TC>::value) {
2493	        static int num_sm = 0;
2494	        if (num_sm == 0) { int dev = 0; cudaGetDevice(&dev); cudaDeviceGetAttribute(&num_sm, cudaDevAttrMultiProcessorCount, dev); if (num_sm <= 0) num_sm = 132; }
2495	        const long total_work = (long)tiles_m * hkv * b;
2496	        const bool q_contig = (q.stride(2) == 1) && (q.stride(1) == (int64_t)HD);
2497	        // rep==1 -> 2D contiguous Q box; packed-GQA (rep>1, rep|CM) -> 3D Q box. Both reload Q via one
2498	        // async TMA so the persistent ring's per-item Q cost stays hidden (the gather reload regressed).
2499	        const bool persist_q_ok = q_contig && (rep == 1 || (rep > 1 && (CM % rep == 0)));
2500	        if (!paged && persist_q_ok && num_splits <= 1 && total_work >= 2L * num_sm) {
2501	            CUtensorMap mapQ = (rep == 1) ? make_kv_map_contig<TC>(q, CM) : make_q_map_gqa<TC>(q, rep, CM);
2502	            constexpr int QBUF = 1, SDEPTH = 2;   // must match prefill_persist_kernel
2503	            int smem_p = (int)((QBUF * CM * HDsm + PSTAGES * CN * HDsm + PSTAGES * CN * HDVsm) * (int)sizeof(TC))
2504	                         + (2 * PSTAGES + 2 * QBUF + 2 * SDEPTH) * (int)sizeof(uint64_t) + SDEPTH * (int)sizeof(int);
2505	            auto wctr = at::empty({1}, q.options().dtype(at::kInt));
2506	            cudaMemsetAsync(wctr.data_ptr<int>(), 0, sizeof(int), stream);
2507	            static bool attr_set_p = false;
2508	            if (!attr_set_p) { cudaFuncSetAttribute(prefill_persist_kernel<TIn, TC, HD, HDV, TMA, EXTRA, PSTAGES, CN, CM, MINB>, cudaFuncAttributeMaxDynamicSharedMemorySize, smem_p); attr_set_p = true; }
