2511	                (const TIn*)q.data_ptr(), (const TIn*)k.data_ptr(), (const TIn*)v.data_ptr(),
2512	                (TC*)out.data_ptr(), (float*)lse.data_ptr(),
2513	                (const int*)cu_q.data_ptr(), cu_k ? (const int*)cu_k->data_ptr() : nullptr,
2514	                seqused_k ? (const int*)seqused_k->data_ptr() : nullptr,
2515	                paged ? (const int*)page_table->data_ptr() : nullptr,
2516	                q_row, q_head, k_row, k_head, v_row, v_head, o_row, o_head,
2517	                hkv, rep, total_q, block_size, page_stride, (float)scale, causal ? 1 : 0,
2518	                (float)softcap, win_l, win_r, qd, kd, vd, ds_b, ds_h, tiles_m, b,
