1255	        // requests, pinning L1TEX (NCU paged prefill: 74.6% mem-pipe, 40% stall on the load scoreboard,
1256	        // DRAM only 4.6%). Here TPR=HD/8 consecutive lanes cooperate on ONE row (each issues one 16B
1257	        // chunk), so a row's HD*2 bytes are one coalesced burst -> ~2x fewer L1TEX sectors. To avoid the
1258	        // per-row dependent page_table LDG (an earlier inline-__shfl coop tried that and serialized 2x),
1259	        // physical rows are PREFETCHED into smem in a coalesced pass, decoupled by a producer-WG barrier;
1260	        // the coalesced load then reads sPR[] (short-scoreboard smem, no global dep). Matches vLLM/FA3's
1261	        // PagedKVManager (kGmemThreadsPerRow + decoupled load_page_table). Writes remain koffR/voffR
1262	        // (byte-identical to the wgmma consumer) and full[]=NumProd arrivals are unchanged.
1263	        constexpr bool COOP = std::is_same<TIn, TC>::value && (HD == HDV) &&
1264	                              (HD % 64 == 0) && (HD / 64 >= 1);
1265	        if constexpr (COOP) {
1266	            // FA3 PagedKVManager granularity: TPR=8 lanes/row (kGmemThreadsPerRow), each issuing KIT=HD/64
1267	            // consecutive 16B (8-bf16) chunks -> each row is loaded as HD/64 x 128-byte coalesced bursts
1268	            // (one cache line each), matching FA3's access pattern. RPP=16 rows resolved per producer pass;
1269	            // each lane resolves ONE page entry (spread across all 128 lanes) and __shfl broadcasts the
1270	            // physical row to the 8 lanes cooperating on it (barrier-free -- no smem prefetch, no page bar).
1271	            constexpr int TPR = 8;
1272	            constexpr int KIT = HD / 64;         // 16B chunks per lane per row (2 for hd128)
1273	            constexpr int RPP = WG / TPR;        // rows resolved per pass (16)
1274	            static_assert(CN % RPP == 0, "COOP gather requires RPP | CN");
1275	            constexpr int RPT = CN / RPP;        // rows each lane strides over (also page entries/lane)
1276	            const int col_th = pt % TPR;         // 0..7
1277	            const int rowsub = pt / TPR;         // 0..RPP-1
1278	            const int rsw = (pt & 31) / TPR;     // rowsub within warp (shfl source-lane base)
1279	            const int kbase = (int)(cu_k ? cu_k[bi] : 0);
1280	            // Paged block_size is a power of two (all vLLM/bench paged caches): resolve the page index /
1281	            // offset with shift/mask instead of `key / block_size` + `key % block_size`. block_size is a
1282	            // RUNTIME int, so nvcc otherwise emits the full ~15-20-instruction software idiv/imod PER KEY
1283	            // (128 lanes each resolve 1 key/tile) in the producer -- pure issue-slot waste competing with
1284	            // cp.async (same axis the offset-broadcast win freed). FA3 uses cutlass::FastDivmod here.
1285	            const int bshift = block_size > 0 ? (31 - __clz((unsigned)block_size)) : 0;
1286	            const int bmask  = block_size - 1;
1287	            for (int li = 0; li < n_cnt; ++li) {
1288	                const int nb = n_lo + li;
1289	                const int st = li % STAGES;
1290	                if (li >= STAGES) { int ep = ((li / STAGES) - 1) & 1; while (!mbar_try_wait(&empty[st], ep)) {} }
1291	                int ent = -1;                    // this lane's resolved physical row (for row rowsub+col_th*RPP)
1292	                if (col_th < RPT) {
1293	                    const int key = nb * CN + rowsub + col_th * RPP;
1294	                    const bool kv = key < seqlen_k;
1295	                    if (page_table) {
1296	                        int blk = kv ? page_table[(long)bi * page_stride + (key >> bshift)] : -1;
1297	                        ent = kv ? (blk << bshift) + (key & bmask) : -1;
1298	                    } else {
1299	                        ent = kv ? kbase + key : -1;
1300	                    }
1301	                }
1302	                TC* sKp = sK0 + st * KSTRIDE; TC* sVp = sV0 + st * VSTRIDE;
1303	                const uint32_t sKa = (uint32_t)__cvta_generic_to_shared(sKp);
1304	                const uint32_t sVa = (uint32_t)__cvta_generic_to_shared(sVp);
1305	                // FA3 PagedKVManager: the int64 K/V row OFFSET is computed ONCE by the row's resolving lane
1306	                // (ent*stride, a 64-bit IMAD) and shfl-broadcast to the 8 cooperating lanes, instead of each
1307	                // of the 8 recomputing ent*stride (8x redundant int64 muls competing with cp.async for issue
